*/

/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, ThinkingLevel } from '@google/genai';
import { Terminal, Image as ImageIcon, MapPin, CloudRain, Settings, Activity, Menu, X, Download, Key, ExternalLink } from 'lucide-react';

// Removed top-level ai initialization to ensure fresh key usage

const staticFilesUrl = 'https://www.gstatic.com/aistudio/starter-apps/window_seat/';

interface TemplateImage {
  id: string;
  imageUrl: string;
  location: string;
  specific_view: string;
  aspect_ratio: string;
}

interface GroundingSource {
  domain: string;
  uri: string;
}

const TEMPLATE_IMAGES: TemplateImage[] = [
  {
    id: '1',
    imageUrl: staticFilesUrl + 'espiritu_pampa.png',
    location: "Peru",
    specific_view: "Espiritu Pampa",
    aspect_ratio: "21:9"
  },
  {
    id: '2',
    imageUrl: staticFilesUrl + 'overijse_david.png',
    location: "Overijse, Belgium",
    specific_view: "Michelangelo's David",
    aspect_ratio: "2:3"
  },
  {
    id: '3',
    imageUrl: staticFilesUrl + 'lake_district.png',
    location: "Lake District, UK",
    specific_view: "Skiddaw House",
    aspect_ratio: "21:9"
  },
];

export default function App() {
  const [location, setLocation] = useState(TEMPLATE_IMAGES[0].location);
  const [specificView, setSpecificView] = useState(TEMPLATE_IMAGES[0].specific_view);
  const [weatherMode, setWeatherMode] = useState<'realtime' | 'manual'>('realtime');
  const [manualWeather, setManualWeather] = useState('Heavy rain, neon reflections');
  const [aspectRatio, setAspectRatio] = useState(TEMPLATE_IMAGES[0].aspect_ratio);

  const [isGenerating, setIsGenerating] = useState(false);
  const [statusMessage, setStatusMessage] = useState('SYSTEM IDLE');
  const [weatherData, setWeatherData] = useState('');
  const [generatedImage, setGeneratedImage] = useState('');
  const [error, setError] = useState('');
  const [groundingSources, setGroundingSources] = useState<GroundingSource[]>([]);

  const [hasInteracted, setHasInteracted] = useState(false);
  const [templateIndex, setTemplateIndex] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showKeyDialog, setShowKeyDialog] = useState(false);

  useEffect(() => {
    if (hasInteracted) return;

    const interval = setInterval(() => {
      setTemplateIndex((prev) => {
        const nextIndex = (prev + 1) % TEMPLATE_IMAGES.length;
        setLocation(TEMPLATE_IMAGES[nextIndex].location);
        setSpecificView(TEMPLATE_IMAGES[nextIndex].specific_view);
        setAspectRatio(TEMPLATE_IMAGES[nextIndex].aspect_ratio);
        return nextIndex;
      });
    }, 4000);

    return () => clearInterval(interval);
  }, [hasInteracted]);

  const stopRotation = () => {
    if (!hasInteracted) {
      setHasInteracted(true);
    }
  };

  const getRealtimeWeather = async (loc: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY as string });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `What is the current weather in ${loc}? Provide a concise description of the current weather conditions (e.g., temperature, precipitation, cloud cover, special phenomena). Do not include forecasts, just the current state. If the location does not exist, interpret the user's request creatively to provide a fictional weather condition.`,
      config: {
        tools: [{ googleSearch: {} }],
        thinkingConfig: {
          thinkingLevel: ThinkingLevel.LOW,
        },
      } as any
    });

    // Extract grounding sources
    const chunks = (response as any).candidates?.[0]?.groundingMetadata?.groundingChunks;
    const sources: GroundingSource[] = [];
    if (chunks) {
      for (const chunk of chunks) {
        const uri = chunk?.web?.uri;
        if (uri) {
          try {
            sources.push({ domain: new URL(uri).hostname.replace(/^www\./, ''), uri });
          } catch { /* skip malformed URIs */ }
        }
      }
    }
    setGroundingSources(sources);

    return response.text || "Unknown weather conditions.";
  };

  const handleGenerate = async () => {
    if (!location || !specificView) {
      setError("Location and Specific View are required.");
      return;
    }

    // API Key Check
    const isKeySelected = await (window as any).aistudio?.hasSelectedApiKey();
    if (!isKeySelected) {
      setShowKeyDialog(true);
      return;
    }

    setIsGenerating(true);
    setError('');
    setGeneratedImage('');
    setWeatherData('');
    setGroundingSources([]);
    setHasInteracted(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY as string });
      let weather = manualWeather;
      if (weatherMode === 'realtime') {
        setStatusMessage('FETCHING REALTIME METEOROLOGICAL DATA...');
        weather = await getRealtimeWeather(location);
        setWeatherData(weather);
      } else {
        setWeatherData(weather);
      }

      setStatusMessage('SYNTHESIZING VISUAL DATA VIA GEMINI 3.1 FLASH IMAGE...');
      const jsonData = {
        location,
        specific_view: specificView,
        weather,
        aspect_ratio: aspectRatio
      };

      const config = {
        imageConfig: {
          aspectRatio: jsonData.aspect_ratio,
          imageSize: "1K",
        },
        responseModalities: ['IMAGE', 'TEXT'],
      };

      const contents = [
        {
          role: 'user',
          parts: [
            {
              text: `Generate a photorealistic window view poster based on the following JSON data:

              ${JSON.stringify(jsonData)}.

              - Use Image Search to search for an image of the specified place. Use keywords to search for the place.
              - Keep the location and the view as close to the real reference as possible.
              - If the location or view is unrealistic or fictional, create a composition blending both the location and the view into a single scene.
              - Choose ONE specific image for the location and ONE specific image for the view to work with, don't use multiple images. 
              - Choose an an appropriate window frame style for the location, keep the view consistent to the aspect ratio, rather than creating a collage.
              - Reason about how current the time of day, and the weather each affect the view, and add details to the scene.
              - Create an image which includes location name text, and a brief summary of the weather, using graphic design that matches the theme. Don't add any other text.`
            },
          ],
        },
      ];

      const response = await ai.models.generateContentStream({
        model: 'gemini-3.1-flash-image-preview',
        config: config as any,
        contents,
      });

      for await (const chunk of response) {
        if (!chunk.candidates || !chunk.candidates[0].content || !chunk.candidates[0].content.parts) {
          continue;
        }
        for (const part of chunk.candidates[0].content.parts) {
          if (part.inlineData) {
            const mimeType = part.inlineData.mimeType || 'image/png';
            const data = part.inlineData.data;
            setGeneratedImage(`data:${mimeType};base64,${data}`);
          }
        }
      }
      setStatusMessage('SEQUENCE COMPLETE.');
    } catch (err: any) {
      console.error(err);
      const msg = err.message || "";
      if (msg.includes("Requested entity was not found") || msg.includes("404")) {
        setShowKeyDialog(true);
      } else {
        setError(err.message || "An error occurred during generation.");
        setStatusMessage('ERROR ENCOUNTERED.');
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = () => {
    if (!generatedImage) return;
    const link = document.createElement('a');
    link.href = generatedImage;
    link.download = `window-seat-${location.replace(/\s+/g, '-').toLowerCase()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex flex-col lg:flex-row h-full w-full overflow-hidden">
      {/* Mobile Header */}
      <div className="lg:hidden h-14 tech-border-b flex items-center px-4 justify-between bg-[#E4E3E0] shrink-0 z-40">
        <div className="flex items-center gap-2">
          <Terminal size={18} className="text-[#141414]" />
          <h1 className="font-serif italic text-sm uppercase tracking-widest font-bold">Window Seat</h1>
        </div>
        <button
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="p-2 hover:bg-black/5 rounded-full transition-colors"
        >
          {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
        </button>
      </div>

      {/* Sidebar */}
      <div className={`
        fixed lg:relative inset-0 lg:inset-auto z-30 lg:z-10
        w-full lg:w-80 h-full flex flex-col bg-[#E4E3E0] shrink-0
        transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
        tech-border-r
      `}>
        <div className="p-4 tech-border-b hidden lg:flex items-center gap-3">
          <Terminal size={20} className="text-[#141414]" />
          <div>
            <h1 className="font-serif italic text-sm uppercase tracking-widest font-bold">Window Seat</h1>
            <div className="text-[10px] data-value opacity-60">Model: Gemini 3.1 Flash Image</div>
          </div>
        </div>

        <div className="p-6 flex-1 overflow-y-auto flex flex-col gap-8">
          {/* Mobile Close Button (Inside Sidebar) */}
          <div className="lg:hidden flex justify-end mb-4">
            <button onClick={() => setIsSidebarOpen(false)} className="p-2 tech-border rounded-sm data-value text-[10px] uppercase">
              Close Settings
            </button>
          </div>
          {/* Location */}
          <div>
            <label className="col-header flex items-center gap-2 mb-3">
              <MapPin size={14} /> 01. Location
            </label>
            <input
              className="input-field"
              value={location}
              onChange={(e) => {
                setLocation(e.target.value);
                stopRotation();
              }}
              placeholder="e.g. Tokyo, Japan"
            />
          </div>

          {/* Specific View */}
          <div>
            <label className="col-header flex items-center gap-2 mb-3">
              <ImageIcon size={14} /> 02. Specific View
            </label>
            <input
              className="input-field"
              value={specificView}
              onChange={(e) => {
                setSpecificView(e.target.value);
                stopRotation();
              }}
              placeholder="e.g. Shinjuku Gyoen"
            />
          </div>

          {/* Weather Mode */}
          <div>
            <label className="col-header flex items-center gap-2 mb-3">
              <CloudRain size={14} /> 03. Weather Source
            </label>
            <div className="flex gap-6 data-value text-sm mt-2">
              <label className="flex items-center gap-2 cursor-pointer hover:opacity-70 transition-opacity">
                <input
                  type="radio"
                  name="weatherMode"
                  className="accent-[#141414]"
                  checked={weatherMode === 'realtime'}
                  onChange={() => {
                    setWeatherMode('realtime');
                    stopRotation();
                  }}
                />
                Realtime
              </label>
              <label className="flex items-center gap-2 cursor-pointer hover:opacity-70 transition-opacity">
                <input
                  type="radio"
                  name="weatherMode"
                  className="accent-[#141414]"
                  checked={weatherMode === 'manual'}
                  onChange={() => {
                    setWeatherMode('manual');
                    stopRotation();
                  }}
                />
                Manual
              </label>
            </div>
          </div>

          {/* Manual Weather Input */}
          {weatherMode === 'manual' && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-200">
              <label className="col-header block mb-3">03b. Weather Conditions</label>
              <input
                className="input-field"
                value={manualWeather}
                onChange={(e) => {
                  setManualWeather(e.target.value);
                  stopRotation();
                }}
                placeholder="e.g. Heavy rain, neon reflections"
              />
            </div>
          )}

          {/* Aspect Ratio */}
          <div>
            <label className="col-header flex items-center gap-2 mb-3">
              <Settings size={14} /> 04. Window Size (Aspect Ratio)
            </label>
            <select
              className="input-field cursor-pointer"
              value={aspectRatio}
              onChange={(e) => {
                setAspectRatio(e.target.value);
                stopRotation();
              }}
            >
              {['1:1', '9:16', '16:9', '3:4', '4:3', '3:2', '2:3', '5:4', '4:5', '21:9', '4:1', '1:4', '8:1', '1:8'].map(ar => (
                <option key={ar} value={ar}>{ar}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="p-4 tech-border-t bg-[#E4E3E0]">
          <button
            className="btn-primary w-full flex items-center justify-center gap-2"
            onClick={() => {
              handleGenerate();
              setIsSidebarOpen(false);
            }}
            disabled={isGenerating}
          >
            {isGenerating ? (
              <>
                <Activity size={16} className="animate-pulse" />
                Processing...
              </>
            ) : (
              'Initialize Sequence'
            )}
          </button>
        </div>
      </div>

      {/* Main Area */}
      <div className="flex-1 flex flex-col h-full bg-[#E4E3E0] min-w-0 relative overflow-y-auto lg:overflow-hidden">
