import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { Globe, Image as ImageIcon, Download, RefreshCw, Loader2, Sparkles, ChevronDown, Upload, X } from 'lucide-react';

declare global {
  interface Window {
