/* ============================================================================
   100 Tools Kitchen App Styles
   ============================================================================ */

.app-container {
  min-height: 100vh;
  background: #fafafa;
  padding-top: 20px;
  padding-bottom: 60px;
  position: relative;
}

/* Chef's checkered pattern down the sides of the page */
.app-container::before,
.app-container::after {
  content: '';
  position: fixed;
  top: 0;
  bottom: 0;
  width: 24px;
  pointer-events: none;
  z-index: 100;
}

.app-container::before {
  left: 4px;
  background: repeating-linear-gradient(
    to bottom,
    #000 0px, #000 12px,
    #fff 12px, #fff 24px
  ), repeating-linear-gradient(
    to bottom,
    #fff 0px, #fff 12px,
    #000 12px, #000 24px
  );
  background-size: 12px 24px, 12px 24px;
  background-position: 0 0, 12px 0;
  background-repeat: repeat-y;
}

.app-container::after {
  right: 4px;
  background: repeating-linear-gradient(
    to bottom,
    #000 0px, #000 12px,
    #fff 12px, #fff 24px
  ), repeating-linear-gradient(
    to bottom,
    #fff 0px, #fff 12px,
    #000 12px, #000 24px
  );
  background-size: 12px 24px, 12px 24px;
  background-position: 0 0, 12px 0;
  background-repeat: repeat-y;
}

/* Hide checkered pattern on narrow screens */
@media (max-width: 1000px) {
  .app-container::before,
  .app-container::after {
    display: none;
  }
}

.kitchen-app {
  max-width: 900px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  font-family: monospace;
  line-height: 1.3;
}

/* Page Title */
.kitchen-title {
  font-size: 28px;
  font-weight: 600;
  color: #333;
  margin: 0;
  font-family: monospace;
}

.kitchen-subtitle {
  font-size: 14px;
  font-weight: 400;
  color: #666;
  margin: 4px 0 0 0;
  font-family: monospace;
}

/* Challenge Banner */
.challenge-banner {
