  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.function-buttons span {
  white-space: nowrap;
  font-weight: 500;
  color: var(--Neutral-90);
}

.function-buttons .button-group {
  display: flex;
  gap: 12px;
  margin-left: auto;
