 */
function GeminiChat({ agentName = "Gemini Chat" }: GeminiChatProps) {
  return (
    <GeminiCustomConsole
      agentName={agentName}
      displayMode="inline"
      enableOverlayPositionSelector={false}
      showInput={true}
      showLogger={true}
      enableLogStyleSelector={false}
      enableLogFilterSelector={false}
