import { createContext, FC, ReactNode, useContext } from "react";
import { useGeminiAPI, UseCoreAPIResults } from "../hooks/use-gemini-api";

const GeminiAPIContext = createContext<UseCoreAPIResults | undefined>(undefined);

export type GeminiAPIProviderProps = {
  children: ReactNode;
};

export const GeminiAPIProvider: FC<GeminiAPIProviderProps> = ({
  children,
}) => {
  const coreAPI = useGeminiAPI();

  return (
    <GeminiAPIContext.Provider value={coreAPI}>
      {children}
    </GeminiAPIContext.Provider>
  );
};

export const useGeminiAPIContext = () => {
  const context = useContext(GeminiAPIContext);
  if (!context) {
    throw new Error("useGeminiAPIContext must be used wihin a GeminiAPIProvider");
  }
  return context;
};

